async function main(): Promise<void> {
  const o: any = { n: { m: new Map<string, number>() }, list: [new Set<number>()] };
  o.n.m.set("a", 1);
  o.list[0].add(2);
  console.log(o.n.m.get("a"), o.list[0].has(2), o.list[0].size);
  const seen: any[] = [];
  const w: any = { m: new Map<string, number>() };
  w.m.set("a", 1); w.m.set("b", 2);
  w.m.forEach((v: any, k: any) => { seen.push(k + v); });
  console.log(seen.join(","), [...w.m].length);
}
